mkdir -p /tmp/alchemy-probe && cat > /tmp/alchemy-probe/probe.js <<'EOF'
'use strict';
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const ROOT = '<run-project>';
const { createApp } = require(ROOT + '/src/app');

const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-reports-'));
fs.writeFileSync(path.join(reportDir, '..', 'SECRET-OUTSIDE.txt'), 'top secret\n');
const app = createApp({ secret: 's', reportDir, admin: { email: 'admin@x.com', password: 'admin-password', name: 'A' } });

function call(port, method, p, { body, token } = {}) {
  return new Promise((resolve, reject) => {
    const payload = body === undefined ? undefined : JSON.stringify(body);
    const headers = {};
    if (payload !== undefined) headers['content-type'] = 'application/json';
    if (token) headers.authorization = `Bearer ${token}`;
    const req = http.request({ host: '127.0.0.1', port, method, path: p, headers, agent: false }, (res) => {
      const c = [];
      res.on('data', (d) => c.push(d));
      res.on('end', () => {
        const text = Buffer.concat(c).toString('utf8');
        let parsed; try { parsed = JSON.parse(text); } catch {}
        resolve({ status: res.statusCode, body: parsed, text });
      });
    });
    req.on('error', reject);
    req.end(payload);
  });
}

(async () => {
  const port = await app.listen(0);
  const C = (...a) => call(port, ...a);
  const admin = (await C('POST', '/sessions', { body: { email: 'admin@x.com', password: 'admin-password' } })).body.token;
  const mk = async (email) => {
    await C('POST', '/users', { body: { email, password: 'correct-horse', name: 'U' } });
    return (await C('POST', '/sessions', { body: { email, password: 'correct-horse' } })).body.token;
  };
  const alice = await mk('alice@x.com');
  const bob = await mk('bob@x.com');

  // P1 IDOR: bob reads alice's order
  const order = (await C('POST', '/orders', { token: alice, body: { items: [{ sku: 'A', unitPrice: 1, quantity: 1 }] } })).body;
  const idor = await C('GET', `/orders/${order.id}`, { token: bob });
  console.log('P1 IDOR  GET /orders/:id as non-owner ->', idor.status, JSON.stringify(idor.body && { id: idor.body.id, userId: idor.body.userId }));

  // P2 path traversal on report download
  const trav = await C('GET', '/reports/..%2FSECRET-OUTSIDE.txt', { token: admin });
  console.log('P2 TRAV  GET /reports/..%2FSECRET-OUTSIDE.txt ->', trav.status, JSON.stringify(trav.text));

  // P3 pagination totalPages
