'use strict';

function isAmount(value) {
  return typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
    && Math.abs(value * 100 - Math.round(value * 100)) < 1e-6;
}

function toCents(amount) {
  return Math.round(amount * 100);
}

function fromCents(cents) {
  return cents / 100;
}

function totalCents(items) {
  return items.reduce((cents, item) => cents + toCents(item.unitPrice) * item.quantity, 0);
}

module.exports = { isAmount, toCents, fromCents, totalCents };
EOF
cat > src/lib/pagination.js <<'EOF'
'use strict';

const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;

function toPositiveInt(value, fallback) {
  const number = Number.parseInt(value, 10);
  return Number.isInteger(number) && number > 0 ? number : fallback;
}

function paginate(items, query = {}) {
  const pageSize = Math.min(toPositiveInt(query.pageSize, DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE);
  const page = toPositiveInt(query.page, 1);
  const start = (page - 1) * pageSize;
  return {
    items: items.slice(start, start + pageSize),
    page,
    pageSize,
    total: items.length,
    totalPages: Math.max(1, Math.ceil(items.length / pageSize)),
  };
}

module.exports = { paginate };
EOF
