test('a customer cannot read another customer order', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const bob = await signUp('bob@example.com');
  const order = (await call('POST', '/orders', { token: alice, body: { items: ITEMS } })).body;
  assert.equal((await call(`GET`, `/orders/${order.id}`, { token: bob })).status, 404);
});

test('a shipped or delivered order can no longer be cancelled', async (t) => {
  const { call, signUp, adminToken } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const order = (await call('POST', '/orders', { token: alice, body: { items: ITEMS } })).body;
  await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: 30 } });
  await call('POST', `/orders/${order.id}/ship`, { token: adminToken });
  assert.equal((await call('POST', `/orders/${order.id}/cancel`, { token: alice })).status, 409);
  await call('POST', `/orders/${order.id}/deliver`, { token: adminToken });
  assert.equal((await call('POST', `/orders/${order.id}/cancel`, { token: alice })).status, 409);
});

test('totalPages counts every page needed to show every item', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  for (let i = 0; i < 3; i += 1) await call('POST', '/orders', { token: alice, body: { items: ITEMS } });
  const first = await call('GET', '/orders?pageSize=2', { token: alice });
  assert.equal(first.body.total, 3);
  assert.equal(first.body.totalPages, 2);
  assert.equal(first.body.items.length, 2);
  const second = await call('GET', '/orders?page=2&pageSize=2', { token: alice });
  assert.equal(second.body.items.length, 1);
  assert.equal(second.body.totalPages, 2);
  const empty = await call('GET', '/orders?page=9&pageSize=2', { token: alice });
  assert.equal(empty.body.items.length, 0);
  assert.equal(empty.body.totalPages, 2);
});

test('an order total is exact to the cent', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const order = (await call('POST', '/orders', {
    token: alice,
    body: { items: [{ sku: 'TAX-1', unitPrice: 0.1, quantity: 3 }, { sku: 'TAX-2', unitPrice: 0.2, quantity: 1 }] },
  })).body;
  assert.equal(order.total, 0.5);
  const paid = await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: order.total } });
  assert.equal(paid.status, 201);
});
EOF
