cat > test/architecture.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const SRC = path.join(__dirname, '..', 'src');

function sourceFiles(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return sourceFiles(full);
    return entry.isFile() && entry.name.endsWith('.js') ? [full] : [];
  });
}

function requiresOf(file) {
  return [...fs.readFileSync(file, 'utf8').matchAll(/require\('([^']+)'\)/g)].map((match) => match[1]);
}

// Architecture rule: an HTTP route module reaches persistence only through its
// own domain service, so every ownership and visibility check it must apply
// lives in exactly one place. Route modules therefore may not import the store.
test('route modules do not import the store', () => {
  const routeFiles = sourceFiles(SRC).filter((file) => path.basename(file) === 'routes.js');
  assert.ok(routeFiles.length >= 4, `expected route modules under src/, found ${routeFiles.length}`);
  for (const file of routeFiles) {
    const forbidden = requiresOf(file).filter((specifier) => /(^|\/)store(\/|$)/.test(specifier));
    assert.deepEqual(forbidden, [], `${path.relative(SRC, file)} imports the store: ${forbidden.join(', ')}`);
  }
});
EOF
