'use strict';

// A valid amount is a positive number that names an exact number of cents:
// it must round-trip through its cent value, which rejects both more than two
// decimals and magnitudes too large to hold a cent exactly.
function isAmount(value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return false;
  const cents = Math.round(value * 100);
  return Number.isSafeInteger(cents) && cents / 100 === value;
}

function toCents(amount) {
  return Math.round(amount * 100);
}

function fromCents(cents) {
  return cents / 100;
}

function totalCents(items) {
  return items.reduce((cents, item) => cents + toCents(item.unitPrice) * item.quantity, 0);
}

module.exports = { isAmount, toCents, fromCents, totalCents };
