'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const SRC = path.join(__dirname, '..', 'src');

// The population is taken from what src/app.js actually registers, so renaming
// or dropping a route module fails this file instead of silently shrinking the
// set being checked.
function registeredRouteModules() {
  const app = fs.readFileSync(path.join(SRC, 'app.js'), 'utf8');
  return [...app.matchAll(/require\('\.\/([a-z]+)\/routes'\)/g)]
    .map((match) => ({ name: match[1], file: path.join(SRC, match[1], 'routes.js') }));
}

function identifiers(source) {
  return new Set(source.split(/[^A-Za-z0-9_$]+/));
}

test('every route module the app registers exists', () => {
  const registered = registeredRouteModules();
  assert.ok(registered.length >= 4, `expected the app to register route modules, found ${registered.length}`);
  for (const { name, file } of registered) {
    assert.ok(fs.existsSync(file), `src/app.js registers ${name} routes but ${file} is missing`);
  }
});

// Enforced rule, exactly as checked: no route module names the order/user/payment
// store, by import or as an injected dependency - the way the store reached
// src/users/routes.js before this change. This is one dependency edge, not the
// whole layering rule: it does not check direct filesystem or network I/O from a
// route module (src/reports/routes.js legitimately reads and writes its own
// exports). The general form is an import-graph rule and belongs in a linter at
// the authoring and build stages; see PR.md for why that is deferred here.
test('route modules do not reach the store', () => {
  for (const { name, file } of registeredRouteModules()) {
    const names = identifiers(fs.readFileSync(file, 'utf8'));
    for (const forbidden of ['store', 'createStore', 'memoryStore']) {
      assert.ok(!names.has(forbidden), `${name} routes name ${forbidden}; route modules use their domain service instead`);
    }
  }
});
EOF
